const unit11RedesignedVerbs = [
  "abandoned", "accumulated", "advocated", "allocated", "altered", "anticipated",
  "calculated", "clarified", "conducted", "defined", "derived", "detected",
  "expanded", "exposed", "induced", "inspected", "integrated", "manipulated",
  "maximized", "minimized", "modified", "processed", "protected", "restricted",
  "shifted", "specified", "stabilized", "suspended", "terminated", "triggered",
  "validated", "violated"
];

function highlightUnit11Text(text) {
  if (typeof text !== 'string') return text;
  let highlighted = text;
  
  unit11RedesignedVerbs.forEach(verb => {
    const pattern = new RegExp(`\\b(not\\s+)?(be|been|being)\\s+((?:rapidly|explicitly|temporarily|confidently|automatically|strongly|clearly|precisely|thoroughly|successfully|finally|instantly|officially|mutually|independently)\\s+)?${verb}\\b`, 'gi');
    highlighted = highlighted.replace(pattern, (match) => {
      return `<span style="color: #ff6b6b; font-weight: bold;">${match}</span>`;
    });
  });

  const parts = highlighted.split(/(<[^>]+>)/g);
  const modalPattern = /\b(can|cannot|can't|could|couldn't|may|might|mightn't|must|mustn't|should|shouldn't|will|won't|ought\s+(?:not\s+)?to)\b/gi;
  for (let i = 0; i < parts.length; i++) {
    if (!parts[i].startsWith('<')) {
      parts[i] = parts[i].replace(modalPattern, (match) => {
        return `<span style="color: #3498db; font-weight: bold;">${match}</span>`;
      });
    }
  }
  return parts.join('');
}

function buildUnit11RedesignedExercise(sentences, unitId, lessonId, exId, level) {
  const qList = [];
  const shuffle = (arr) => [...arr].sort(() => 0.5 - Math.random());

  if (level === "basit") {
    // Q1: fill-blank (dropdown or standard fill blank)
    const s1 = sentences[0];
    const highlightedEn = highlightUnit11Text(s1.en);
    const blankWord = s1.word;
    const blankEn = highlightedEn.replace(blankWord, "___");
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_fb_${level}_0`,
      type: "fill-blank",
      prompt: "Boşluğu en uygun şekilde doldurun:",
      sentence: blankEn,
      options: shuffle([blankWord, blankWord + "ing", blankWord + "s", "to " + blankWord]),
      correctIndex: 0, // Options will be shuffled, correct index updated by loader or we calculate it
      translation: s1.tr
    });
    // Fix index post-shuffling in the generator
    const q1 = qList[qList.length - 1];
    q1.correctIndex = q1.options.indexOf(blankWord);

    // Q2-Q3: multiple-choice (Eng to Tr)
    for (let i = 1; i <= 2; i++) {
      const sA = sentences[i];
      const wrongs = shuffle(sentences.filter(s => s.en !== sA.en));
      const options = shuffle([sA.tr, wrongs[0].tr, wrongs[1].tr, wrongs[2].tr]);
      qList.push({
        id: `u${unitId}l${lessonId}_ex${exId}_mc_${level}_${i}`,
        type: "multiple-choice",
        prompt: `"${highlightUnit11Text(sA.en)}" cümlesinin Türkçe karşılığı hangisidir?`,
        options: options,
        correctIndex: options.indexOf(sA.tr),
        enSentence: highlightUnit11Text(sA.en),
        isEngToTr: true
      });
    }

    // Q4: Word Bank (Eng to Tr)
    const s4 = sentences[3];
    const targetWords = s4.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherTr = sentences.filter(s => s.en !== s4.en).map(s => s.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueDistractors = [...new Set(allOtherTr)].filter(w => !targetWords.includes(w));
    const shuffledDistractors = shuffle(uniqueDistractors);
    while (shuffledDistractors.length < 3) { shuffledDistractors.push("ve"); }
    const words = shuffle([...targetWords, shuffledDistractors[0], shuffledDistractors[1], shuffledDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_et_${level}_3`,
      type: "word-bank",
      prompt: "Cümlenin Türkçe karşılığını oluşturun:",
      translation: highlightUnit11Text(s4.en),
      words: words,
      correctOrder: targetWords,
      enSentence: highlightUnit11Text(s4.en),
      isEngToTr: true
    });

    // Q5: Word Bank (Tr to Eng)
    const s5 = sentences[4];
    const targetEnWords = s5.en.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherEn = sentences.filter(s => s.en !== s5.en).map(s => s.en.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueEnDistractors = [...new Set(allOtherEn)].filter(w => !targetEnWords.includes(w));
    const shuffledEnDistractors = shuffle(uniqueEnDistractors);
    while (shuffledEnDistractors.length < 3) { shuffledEnDistractors.push("the"); }
    const enWords = shuffle([...targetEnWords, shuffledEnDistractors[0], shuffledEnDistractors[1], shuffledEnDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_te_${level}_4`,
      type: "word-bank",
      prompt: "Cümlenin İngilizce karşılığını oluşturun:",
      translation: s5.tr,
      words: enWords,
      correctOrder: targetEnWords,
      enSentence: highlightUnit11Text(s5.en),
      isEngToTr: false
    });
  } else if (level === "orta") {
    // Q6: fill-blank-dropdown
    const s1 = sentences[0];
    const highlightedEn = highlightUnit11Text(s1.en);
    const blankWord = s1.word;
    const blankEn = highlightedEn.replace(blankWord, "___");
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_fbd_${level}_0`,
      type: "fill-blank-dropdown",
      prompt: "Boşluğa gelecek en uygun kelimeyi seçin:",
      sentence: blankEn,
      options: shuffle([blankWord, blankWord + "ing", blankWord + "ed", "to " + blankWord]),
      correctIndex: 0,
      translation: s1.tr
    });
    const q1 = qList[qList.length - 1];
    q1.correctIndex = q1.options.indexOf(blankWord);

    // Q7-Q8: multiple-choice (Eng to Tr)
    for (let i = 1; i <= 2; i++) {
      const sA = sentences[i];
      const wrongs = shuffle(sentences.filter(s => s.en !== sA.en));
      const options = shuffle([sA.tr, wrongs[0].tr, wrongs[1].tr, wrongs[2].tr]);
      qList.push({
        id: `u${unitId}l${lessonId}_ex${exId}_mc_${level}_${i}`,
        type: "multiple-choice",
        prompt: `"${highlightUnit11Text(sA.en)}" cümlesinin Türkçe karşılığı hangisidir?`,
        options: options,
        correctIndex: options.indexOf(sA.tr),
        enSentence: highlightUnit11Text(sA.en),
        isEngToTr: true
      });
    }

    // Q9: Word Bank (Eng to Tr)
    const s4 = sentences[3];
    const targetWords = s4.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherTr = sentences.filter(s => s.en !== s4.en).map(s => s.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueDistractors = [...new Set(allOtherTr)].filter(w => !targetWords.includes(w));
    const shuffledDistractors = shuffle(uniqueDistractors);
    while (shuffledDistractors.length < 3) { shuffledDistractors.push("ve"); }
    const words = shuffle([...targetWords, shuffledDistractors[0], shuffledDistractors[1], shuffledDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_et_${level}_3`,
      type: "word-bank",
      prompt: "Cümlenin Türkçe karşılığını oluşturun:",
      translation: highlightUnit11Text(s4.en),
      words: words,
      correctOrder: targetWords,
      enSentence: highlightUnit11Text(s4.en),
      isEngToTr: true
    });

    // Q10: Word Bank (Tr to Eng)
    const s5 = sentences[4];
    const targetEnWords = s5.en.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherEn = sentences.filter(s => s.en !== s5.en).map(s => s.en.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueEnDistractors = [...new Set(allOtherEn)].filter(w => !targetEnWords.includes(w));
    const shuffledEnDistractors = shuffle(uniqueEnDistractors);
    while (shuffledEnDistractors.length < 3) { shuffledEnDistractors.push("the"); }
    const enWords = shuffle([...targetEnWords, shuffledEnDistractors[0], shuffledEnDistractors[1], shuffledEnDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_te_${level}_4`,
      type: "word-bank",
      prompt: "Cümlenin İngilizce karşılığını oluşturun:",
      translation: s5.tr,
      words: enWords,
      correctOrder: targetEnWords,
      enSentence: highlightUnit11Text(s5.en),
      isEngToTr: false
    });
  } else if (level === "ileri") {
    // Q11: translation-text
    const s1 = sentences[0];
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_tx_${level}_0`,
      type: "translation-text",
      prompt: `"${highlightUnit11Text(s1.en)}" cümlesini Türkçe'ye çevirin:`,
      correctSentence: s1.tr,
      enSentence: highlightUnit11Text(s1.en),
      isEngToTr: true
    });

    // Q12-Q13: multiple-choice (Eng to Tr)
    for (let i = 1; i <= 2; i++) {
      const sA = sentences[i];
      const wrongs = shuffle(sentences.filter(s => s.en !== sA.en));
      const options = shuffle([sA.tr, wrongs[0].tr, wrongs[1].tr, wrongs[2].tr]);
      qList.push({
        id: `u${unitId}l${lessonId}_ex${exId}_mc_${level}_${i}`,
        type: "multiple-choice",
        prompt: `"${highlightUnit11Text(sA.en)}" cümlesinin Türkçe karşılığı hangisidir?`,
        options: options,
        correctIndex: options.indexOf(sA.tr),
        enSentence: highlightUnit11Text(sA.en),
        isEngToTr: true
      });
    }

    // Q14: Word Bank (Eng to Tr)
    const s4 = sentences[3];
    const targetWords = s4.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherTr = sentences.filter(s => s.en !== s4.en).map(s => s.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueDistractors = [...new Set(allOtherTr)].filter(w => !targetWords.includes(w));
    const shuffledDistractors = shuffle(uniqueDistractors);
    while (shuffledDistractors.length < 3) { shuffledDistractors.push("ve"); }
    const words = shuffle([...targetWords, shuffledDistractors[0], shuffledDistractors[1], shuffledDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_et_${level}_3`,
      type: "word-bank",
      prompt: "Cümlenin Türkçe karşılığını oluşturun:",
      translation: highlightUnit11Text(s4.en),
      words: words,
      correctOrder: targetWords,
      enSentence: highlightUnit11Text(s4.en),
      isEngToTr: true
    });

    // Q15: Word Bank (Tr to Eng)
    const s5 = sentences[4];
    const targetEnWords = s5.en.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherEn = sentences.filter(s => s.en !== s5.en).map(s => s.en.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueEnDistractors = [...new Set(allOtherEn)].filter(w => !targetEnWords.includes(w));
    const shuffledEnDistractors = shuffle(uniqueEnDistractors);
    while (shuffledEnDistractors.length < 3) { shuffledEnDistractors.push("the"); }
    const enWords = shuffle([...targetEnWords, shuffledEnDistractors[0], shuffledEnDistractors[1], shuffledEnDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_te_${level}_4`,
      type: "word-bank",
      prompt: "Cümlenin İngilizce karşılığını oluşturun:",
      translation: s5.tr,
      words: enWords,
      correctOrder: targetEnWords,
      enSentence: highlightUnit11Text(s5.en),
      isEngToTr: false
    });
  }

  return qList;
}

function buildLessonExercises(lessonId) {
  const sPool = unit11RedesignedSentences[lessonId.toString()];
  const qBasit = buildUnit11RedesignedExercise(sPool.basit, 11, lessonId, 1, "basit");
  const qOrta = buildUnit11RedesignedExercise(sPool.orta, 11, lessonId, 1, "orta");
  const qIleri = buildUnit11RedesignedExercise(sPool.ileri, 11, lessonId, 1, "ileri");
  
  return [
    {
      id: `u11l${lessonId}ex1`,
      title: getLessonTitle(lessonId),
      description: getLessonDesc(lessonId),
      questions: [...qBasit, ...qOrta, ...qIleri]
    }
  ];
}

function getLessonTitle(lessonId) {
  switch(lessonId) {
    case 32: return "Alıştırma 1: Pozitif Edilgen Mastar Modalları";
    case 33: return "Alıştırma 1: Olumsuz Edilgen Mastar Modalları";
    case 34: return "Alıştırma 1: Soru Biçimindeki Edilgen Modallar";
    case 35: return "Alıştırma 1: Eyleyeni Belirtilen Edilgen Modallar (by + Agent)";
    case 36: return "Alıştırma 1: Bölünmüş Edilgen Fiiller (Split Passives)";
    case 37: return "Alıştırma 1: Karmaşık ve Bölünmüş Edilgen Yapılar";
    default: return "Alıştırma 1: Edilgen Yapılar";
  }
}

function getLessonDesc(lessonId) {
  switch(lessonId) {
    case 32: return "Olumlu edilgen modal (can/must/should/will be + V3) yapılarının pratikleri.";
    case 33: return "Olumsuz edilgen modal (cannot/must not/should not be + V3) pratikleri.";
    case 34: return "Soru biçimlerindeki edilgen modal (Can/Should/Must ... be + V3) pratikleri.";
    case 35: return "Eylemi gerçekleştirenin (by + Özne) belirtildiği karmaşık edilgen modal cümleleri.";
    case 36: return "Edilgen fiil arasına zarf giren (is/was + adverb + V3) bölünmüş yapıların pekiştirilmesi.";
    case 37: return "Karmaşık eyleyenli ve zarf bölünmeli edilgen modal yapıların kombine edildiği ileri seviye pratikler.";
    default: return "Edilgen mastar ve bölünmüş edilgen yapı pratikleri.";
  }
}

