// --- BUILDER FUNCTION ---
function buildUnit12RedesignedExercise(sentences, unitId, lessonId, exId, level) {
  const qList = [];
  const shuffle = (arr) => [...arr].sort(() => 0.5 - Math.random());
  
  // 1. Phrase Matching (Q1) - uses sentences 0, 1, 2, 3
  const matchSents = sentences.slice(0, 4);
  qList.push({
    id: `u${unitId}l${lessonId}_ex${exId}_match_${level}`,
    type: "matching",
    prompt: "İfadeleri Türkçe karşılıklarıyla eşleştirin.",
    pairs: matchSents.map(s => ({
      left: s.tr,
      right: s.en
    }))
  });

  // Helper for generating distractors
  const getTrDistractors = (sA, count = 3) => {
    const wrongs = shuffle(sentences.filter(s => s.en !== sA.en));
    return wrongs.slice(0, count).map(s => s.tr);
  };

  // 2. Multiple Choice En -> Tr (Q2) - uses sentence 4
  {
    const sA = sentences[4];
    const distractors = getTrDistractors(sA);
    const options = shuffle([sA.tr, ...distractors]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_mc_et_${level}_4`,
      type: "multiple-choice",
      prompt: level === "basit" ? `"${sA.en}" ifadesinin Türkçe karşılığı hangisidir?` : `"${sA.en}" cümlesinin Türkçe karşılığı hangisidir?`,
      options: options,
      correctIndex: options.indexOf(sA.tr),
      enSentence: sA.en,
      isEngToTr: true
    });
  }

  // 3. Word Bank En -> Tr (Q3) - uses sentence 5
  {
    const sA = sentences[5];
    const targetWords = sA.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""));
    const allOtherTr = sentences.filter(s => s.en !== sA.en).map(s => s.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""))).flat();
    const uniqueDistractors = [...new Set(allOtherTr)].filter(w => !targetWords.includes(w));
    const shuffledDistractors = shuffle(uniqueDistractors);
    while (shuffledDistractors.length < 3) { shuffledDistractors.push("ve"); }
    const words = shuffle([...targetWords, shuffledDistractors[0], shuffledDistractors[1], shuffledDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_et_${level}_5`,
      type: "word-bank",
      prompt: level === "basit" ? "İfadenin Türkçe karşılığını oluşturun:" : "Cümlenin Türkçe karşılığını oluşturun:",
      translation: sA.en,
      words: words,
      correctOrder: targetWords,
      enSentence: sA.en,
      isEngToTr: true
    });
  }

  // 4. Fill in the Blank Dropdown (Q4) - uses sentence 6
  {
    const sA = sentences[6];
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_fb_${level}_6`,
      type: "fill-blank-dropdown",
      prompt: "Boşluğa gelecek en uygun kelimeyi seçin:",
      sentence: sA.blank || sA.en.replace(sA.word, "___"),
      options: sA.options || [sA.word, sA.word + "s", sA.word + "ed", sA.word + "ing"].filter((v, idx, self) => self.indexOf(v) === idx),
      correctIndex: (sA.options || [sA.word, sA.word + "s", sA.word + "ed", sA.word + "ing"]).indexOf(sA.word),
      enSentence: sA.en
    });
  }

  // 5. Translation Text En -> Tr (Q5) - uses sentence 7
  {
    const sA = sentences[7];
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_tx_et_${level}_7`,
      type: "translation-text",
      prompt: level === "basit" ? `"${sA.en}" ifadesini Türkçe'ye çevirin:` : `"${sA.en}" cümlesini Türkçe'ye çevirin:`,
      correctSentence: sA.tr,
      enSentence: sA.en,
      isEngToTr: true
    });
  }

  return qList;
}

